import os, glob, re, json

def load_grids():
    """Load all grids from the session (demo pairs + test input)"""
    d = os.environ['RLM_SESSION_DIR']
    t_file = os.path.join(d, '..', os.path.basename(d) + '.jsonl')

    if os.path.exists(t_file):
        with open(t_file, 'r') as f:
            content = f.read()

        grids = {}
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        m = re.search(pattern, content)

        if m:
            key, kind, h, w = m.groups()
            h, w = int(h), int(w)

            # Extract grid rows
            start = m.end()
            lines = [line.strip() for line in content[start:].split('\n')[:h]]

            for i, line in enumerate(lines):
                if line and line.replace(' ', ''):
                    grids.setdefault(key, []).append([int(x) for x in line.split()])

            if grids:
                # Check if last entry is complete
                last_key = list(grids.keys())[-1]
                grid = grids[last_key]
                if len(grid[0]) != int(w):
                    grids.clear()

        return grids
    return {}

G = load_grids()
print("Grids loaded:", sorted(G.keys())[:5])

# Check if we have any demo pairs
if G:
    for key in sorted(G)[:2]:
        print(f"\n=== {key} ===")
        print(G[key])

